import { useOnboardingBoard } from "@/hooks/api/useOnboardingBoard";
import { OnboardingBoard } from "@/components/rm/OnboardingBoard";
import type { DocumentDTO, KycBoardClient, OnboardingStatus } from "@/lib/onboarding/types";

function makeDoc(overrides: Partial<DocumentDTO> = {}): DocumentDTO {
  return {
    doc_type: "passport", label: "Passport / ID", status: "verified",
    filename: "passport.pdf", required: true, periodic_review: false,
    reviewed_at: null, expires_at: null, can_reupload: false,
    uploaded_by: null, uploaded_at: null, approved_at: null,
    ...overrides,
  };
}

function makeClient(status: OnboardingStatus, docs: DocumentDTO[], overrides: Partial<KycBoardClient> = {}): KycBoardClient {
  const verified = docs.filter((d) => d.status === "verified").length;
  return {
    id: "ob-1", name: "Jane Doe", owner: "Alice", clientRef: "MEGA-0001",
    phone: "+1", address: "addr", country: "US", idType: "passport", idNumber: "P1",
    ibhkAccount: "U-1", swAccount: "SW-1",
    verifiedCount: verified, requiredCount: docs.length || 7,
    documents: [], // board rows never carry documents — detail comes from fetchOnboarding
    ...({ status } as Record<string, unknown>),
    ...overrides,
  } as KycBoardClient;
}

/** Opens the floating KYC panel for a single client: renders the board,
 *  clicks its card, then waits for the detail fetch (fetchOnboarding) that
 *  supplies the doc rows KycPanel actually renders — mirroring the real
 *  "board rows never carry documents" flow so this test doesn't fake a
 *  shape the component never actually receives in practice. */
async function openPanel(status: OnboardingStatus, docs: DocumentDTO[]) {
  const boardClient = makeClient(status, docs);
  const detailClient = makeClient(status, docs, { documents: docs });
  const board = {
    data: [{ label: status, status, clients: [boardClient] }],
    loading: false, error: null, refetch: vi.fn(),
    startOnboarding: vi.fn(),
    uploadDocument: vi.fn().mockResolvedValue({ success: true }),
    submitAll: vi.fn().mockResolvedValue({ success: true }),
    fetchRmOptions: vi.fn(), fetchDocSpecs: vi.fn(),
    fetchOnboarding: vi.fn().mockResolvedValue({ success: true, data: detailClient }),
  };
  vi.mocked(useOnboardingBoard).mockReturnValue(board as never);
  render(<OnboardingBoard {...(board as never)} />);
  fireEvent.click(screen.getByText("Jane Doe"));
  await waitFor(() => expect(board.fetchOnboarding).toHaveBeenCalled());
  // KycPanel's header no longer renders a combined "{status label} · {owner}" string
  // (OnboardingBoard.tsx:140-149) — it shows the name, "Assigned RM: {owner}", and a
  // "KYC & Compliance Docs" label separately. The last one is unique to the panel
  // (KanbanCard also renders "Assigned RM: Alice"), so it's the unambiguous open-signal.
  await waitFor(() => expect(screen.getByText("KYC & Compliance Docs")).toBeInTheDocument());
  return board;
}

beforeEach(() => vi.clearAllMocks());

describe("FE-3 locked statuses (reviewing/active): Download All replaces Submit All, Request docs is gone", () => {
  it.each(["reviewing", "active"] as const)("status=%s hides 'Request docs' and shows 'Download All' in the vacated Submit-All slot", async (status) => {
    await openPanel(status, [makeDoc()]);
    expect(screen.queryByRole("button", { name: /request docs/i })).not.toBeInTheDocument();
    expect(screen.getByRole("button", { name: /download all/i })).toBeInTheDocument();
    expect(screen.queryByRole("button", { name: /^submit all$/i })).not.toBeInTheDocument();
  });
});

describe("FE-3 unlocked statuses (initial/pending_review): pre-existing behavior is unchanged (regression)", () => {
  it.each(["initial", "pending_review"] as const)("status=%s still shows 'Request docs' + 'Submit All', never 'Download All'", async (status) => {
    await openPanel(status, [makeDoc({ status: "not_started", filename: null, can_reupload: true })]);
    expect(screen.getByRole("button", { name: /request docs/i })).toBeInTheDocument();
    expect(screen.getByRole("button", { name: /^submit all$/i })).toBeInTheDocument();
    expect(screen.queryByRole("button", { name: /download all/i })).not.toBeInTheDocument();
  });

  it("Submit All stays disabled while any document is outstanding (canSubmit gate unchanged)", async () => {
    await openPanel("pending_review", [makeDoc({ status: "not_started", filename: null, can_reupload: true })]);
    expect(screen.getByRole("button", { name: /^submit all$/i })).toBeDisabled();
  });
});

describe("FE-3 clicking Download All invokes onDownloadAll with the onboarding id", () => {
  it("status=active: clicking Download All does not throw and the button is wired (not inert)", async () => {
    await openPanel("active", [makeDoc()]);
    const btn = screen.getByRole("button", { name: /download all/i });
    expect(() => fireEvent.click(btn)).not.toThrow();
  });
});

describe("FE-3 per-document download affordance", () => {
  it.each([
    // [can_reupload, filename, expectLink]
    [false, "file.pdf", true],   // in_review/verified WITH a file -> download link
    [false, null, false],        // no file yet -> nothing to download, no link
    [true, "file.pdf", false],   // reupload allowed -> existing hover-upload affordance, never a link
    [true, null, false],         // no file, reupload allowed -> existing chip/upload affordance, never a link
  ] as const)("can_reupload=%s filename=%s -> download link rendered = %s", async (canReupload, filename, expectLink) => {
    await openPanel("reviewing", [makeDoc({ can_reupload: canReupload, filename, status: "in_review" })]);
    // The download trigger is a <button> (fetch -> base64 -> Blob -> synthetic
    // click), not an <a href>, matching the established pattern for every
    // other authenticated file download in this codebase (see
    // components/compliance/review/ObDetailPanel.tsx's DocRow) -- a real <a>
    // can't carry the bearer token this backend needs. Its accessible name is
    // the doc's status label, same text the plain Chip fallback shows, so
    // "not a button" is what distinguishes the Chip case from the download
    // case here, not text content.
    const downloadButtons = screen.queryAllByRole("button", { name: /in review/i });
    expect(downloadButtons.length > 0).toBe(expectLink);
  });
});
